head.script:
// deleteSubmission 호출 결과와 호출 중 출력된 console 오류를 표시한다
scwin.callDelete = function (name, sId) {
    let arrErr = [];
    let fnError = console.error;
    let fnLog = console.log;
    let fnCatch = function () {
        let sMsg = Array.prototype.join.call(arguments, " ");
        if (sMsg.indexOf("Error") > -1) {
            arrErr.push(sMsg.split("\n")[0]);
        }
    };
    console.error = function () { fnCatch.apply(null, arguments); return fnError.apply(console, arguments); };
    console.log = function () { fnCatch.apply(null, arguments); return fnLog.apply(console, arguments); };
    let ret;
    try {
        ret = $p.deleteSubmission(sId);
    } finally {
        console.error = fnError;
        console.log = fnLog;
    }
    scwin.setReturnValue("[" + name + "] $p.deleteSubmission(\"" + sId + "\")");
    scwin.setReturnValue("  리턴 값 : " + (ret && typeof ret === "object" ? "id=" + ret.id : String(ret)) + " / typeof : " + typeof ret + " / === null : " + (ret === null));
    scwin.setReturnValue("  console 오류 : " + (arrErr.length > 0 ? arrErr.join(" | ") : "없음"));
};

scwin.btn_a_onclick = function () { scwin.callDelete("A", "sbm_none"); };
scwin.btn_b_onclick = function () { scwin.callDelete("B", "sbm_a"); };

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
